export async function test_api_member_email_verification_index(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin connection for accessing verification records
  const adminConnection: api.IConnection = { host: connection.host };
  // 2. Call the email verification listing endpoint with default parameters
  const result =
    await api.functional.multiUserTodo.member_email_verifications.index(
      adminConnection,
      {
        body: {},
      },
    );
  typia.assert(result);
  // 3. Verify pagination structure exists and has correct type
  typia.assert(result.pagination);
  // Verify pagination metadata fields exist and are valid
  TestValidator.predicate(
    "pagination current is non-negative",
    result.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit is positive",
    result.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    result.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    result.pagination.pages >= 0,
  );
  // Verify pages calculation is correct: ceil(records / limit)
  const expectedPages =
    result.pagination.records > 0
      ? Math.ceil(result.pagination.records / result.pagination.limit)
      : 0;
  TestValidator.equals(
    "pagination pages calculated correctly",
    result.pagination.pages,
    expectedPages,
  );
  // 4. Verify data array exists and is an array
  typia.assert(result.data);
  TestValidator.predicate("data is an array", Array.isArray(result.data));
  // 5. Verify data count matches pagination records
  TestValidator.equals(
    "data length matches records count",
    result.data.length,
    result.pagination.records,
  );
  // 6. If there are verification records, validate their structure
  if (result.data.length > 0) {
    // Process first record to validate structure
    const firstRecord = result.data[0];
    typia.assert(firstRecord);
    // Verify required fields exist
    TestValidator.equals("verification has id", !!firstRecord.id, true);
    TestValidator.equals("verification has email", !!firstRecord.email, true);
    TestValidator.equals(
      "verification has expires_at",
      !!firstRecord.expires_at,
      true,
    );
    TestValidator.equals(
      "verification has created_at",
      !!firstRecord.created_at,
      true,
    );
    TestValidator.equals("verification has member", !!firstRecord.member, true);
    // Verify id is valid UUID format
    const uuidPattern =
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    TestValidator.equals(
      "id is valid UUID format",
      uuidPattern.test(firstRecord.id),
      true,
    );
    // Verify email is valid email format
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    TestValidator.equals(
      "email is valid format",
      emailPattern.test(firstRecord.email),
      true,
    );
    // Verify timestamps are valid ISO datetime
    TestValidator.equals(
      "created_at is valid ISO datetime",
      !isNaN(Date.parse(firstRecord.created_at)),
      true,
    );
    TestValidator.equals(
      "expires_at is valid ISO datetime",
      !isNaN(Date.parse(firstRecord.expires_at)),
      true,
    );
    // Verify expires_at is after created_at (token valid at creation)
    TestValidator.predicate(
      "expires_at is after created_at",
      new Date(firstRecord.expires_at).getTime() >
        new Date(firstRecord.created_at).getTime(),
    );
    // Verify member object structure
    typia.assert(firstRecord.member);
    TestValidator.equals("member has id", !!firstRecord.member.id, true);
    TestValidator.equals("member has email", !!firstRecord.member.email, true);
    TestValidator.equals(
      "member has created_at",
      !!firstRecord.member.created_at,
      true,
    );
    TestValidator.equals(
      "member has updated_at",
      !!firstRecord.member.updated_at,
      true,
    );
    TestValidator.predicate(
      "member deleted_at is null or string",
      firstRecord.member.deleted_at === null ||
        typeof firstRecord.member.deleted_at === "string",
    );
    // Verify member email matches verification email
    TestValidator.equals(
      "member email matches verification email",
      firstRecord.member.email,
      firstRecord.email,
    );
  }
  // 7. Verify default sort order if multiple records exist
  if (result.data.length > 1) {
    // Check first two records for descending order by created_at
    const firstCreated = new Date(result.data[0].created_at).getTime();
    const secondCreated = new Date(result.data[1].created_at).getTime();
    TestValidator.predicate(
      "results sorted by created_at descending (first two)",
      firstCreated >= secondCreated,
    );
  }
  // 8. Verify pagination metadata consistency
  if (result.pagination.records > 0) {
    TestValidator.equals(
      "current page is 1 when limit < records",
      result.pagination.current,
      1,
    );
  }
  // 9. Verify data type safety - all items in array have same structure
  if (result.data.length > 1) {
    const firstRecord = result.data[0];
    const lastRecord = result.data[result.data.length - 1];
    typia.assert(firstRecord);
    typia.assert(lastRecord);
    TestValidator.equals(
      "all records have id field",
      !!lastRecord.id,
      !!firstRecord.id,
    );
    TestValidator.equals(
      "all records have email field",
      !!lastRecord.email,
      !!firstRecord.email,
    );
    TestValidator.equals(
      "all records have member field",
      !!lastRecord.member,
      !!firstRecord.member,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IMultiUserTodoMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoMember";
import type { IMultiUserTodoMemberEmailVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IMultiUserTodoMemberEmailVerification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIMultiUserTodoMemberEmailVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMultiUserTodoMemberEmailVerification";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

export async function test_api_member_email_verification_filter_by_status(
  connection: api.IConnection,
): Promise<void> {
  // Create actor-specific connection for admin operations
  const adminConnection: api.IConnection = { host: connection.host };
  // Get baseline - all verification records without status filter
  const allVerifications =
    await api.functional.multiUserTodo.member_email_verifications.index(
      adminConnection,
      {
        body: {
          pagination: { limit: 100 },
        },
      },
    );
  typia.assert(allVerifications);
  // Test active filter - should return only non-expired tokens
  const activeVerifications =
    await api.functional.multiUserTodo.member_email_verifications.index(
      adminConnection,
      {
        body: {
          status: "active",
          pagination: { limit: 100 },
        },
      },
    );
  typia.assert(activeVerifications);
  // Validate all active verifications are actually active (expires_at > current time)
  const currentTime = new Date();
  for (const verification of activeVerifications.data) {
    const expiresAtDate = new Date(verification.expires_at);
    TestValidator.predicate(
      "active verification expires_at in future",
      expiresAtDate > currentTime,
    );
  }
  // Test expired filter - should return only expired tokens (expires_at <= current time)
  const expiredVerifications =
    await api.functional.multiUserTodo.member_email_verifications.index(
      adminConnection,
      {
        body: {
          status: "expired",
          pagination: { limit: 100 },
        },
      },
    );
  typia.assert(expiredVerifications);
  // Validate all expired verifications are actually expired (expires_at <= current time)
  for (const verification of expiredVerifications.data) {
    const expiresAtDate = new Date(verification.expires_at);
    TestValidator.predicate(
      "expired verification expires_at in past",
      expiresAtDate <= currentTime,
    );
  }
  // Verify filters are mutually exclusive - no overlap between active and expired results
  const activeIds = new Set(activeVerifications.data.map((v) => v.id));
  const expiredIds = new Set(expiredVerifications.data.map((v) => v.id));
  for (const activeId of activeIds) {
    TestValidator.predicate(
      "no overlap - active id not found in expired set",
      !expiredIds.has(activeId),
    );
  }
  // Verify pagination counts match filtered results
  TestValidator.equals(
    "active pagination records count matches data length",
    activeVerifications.pagination.records,
    activeVerifications.data.length,
  );
  TestValidator.equals(
    "expired pagination records count matches data length",
    expiredVerifications.pagination.records,
    expiredVerifications.data.length,
  );
  // Test sorting with active filter - descending by expires_at
  const activeSortedByExpiresDesc =
    await api.functional.multiUserTodo.member_email_verifications.index(
      adminConnection,
      {
        body: {
          status: "active",
          sort_by: "expires_at",
          sort_order: "desc",
          pagination: { limit: 50 },
        },
      },
    );
  typia.assert(activeSortedByExpiresDesc);
  // Verify sorted order (descending by expires_at)
  if (activeSortedByExpiresDesc.data.length > 1) {
    for (let i = 1; i < activeSortedByExpiresDesc.data.length; i++) {
      const prev = activeSortedByExpiresDesc.data[i - 1];
      const curr = activeSortedByExpiresDesc.data[i];
      const prevExpires = new Date(prev.expires_at);
      const currExpires = new Date(curr.expires_at);
      TestValidator.predicate(
        "active sorted desc by expires_at",
        prevExpires >= currExpires,
      );
    }
  }
  // Test sorting with expired filter - ascending by created_at
  const expiredSortedByCreatedAsc =
    await api.functional.multiUserTodo.member_email_verifications.index(
      adminConnection,
      {
        body: {
          status: "expired",
          sort_by: "created_at",
          sort_order: "asc",
          pagination: { limit: 50 },
        },
      },
    );
  typia.assert(expiredSortedByCreatedAsc);
  // Verify sorted order (ascending by created_at)
  if (expiredSortedByCreatedAsc.data.length > 1) {
    for (let i = 1; i < expiredSortedByCreatedAsc.data.length; i++) {
      const prev = expiredSortedByCreatedAsc.data[i - 1];
      const curr = expiredSortedByCreatedAsc.data[i];
      const prevCreated = new Date(prev.created_at);
      const currCreated = new Date(curr.created_at);
      TestValidator.predicate(
        "expired sorted asc by created_at",
        prevCreated <= currCreated,
      );
    }
  }
  // Test combined filters - email + status (if we have any records)
  if (allVerifications.data.length > 0) {
    const testEmail = allVerifications.data[0].email;
    const filteredWithEmail =
      await api.functional.multiUserTodo.member_email_verifications.index(
        adminConnection,
        {
          body: {
            email: testEmail,
            status: "active",
            pagination: { limit: 100 },
          },
        },
      );
    typia.assert(filteredWithEmail);
    // Verify all results match the email filter
    for (const verification of filteredWithEmail.data) {
      TestValidator.equals(
        "email filter matches returned verifications",
        verification.email,
        testEmail,
      );
    }
  }
  // Test pagination beyond results
  const paginationBeyond =
    await api.functional.multiUserTodo.member_email_verifications.index(
      adminConnection,
      {
        body: {
          status: "active",
          pagination: { limit: 1, page: 100 },
        },
      },
    );
  typia.assert(paginationBeyond);
  TestValidator.equals(
    "pagination beyond results returns empty array",
    paginationBeyond.data.length,
    0,
  );
}

